var n=`1074-sinigang-na-baboy`;var a=`world-1074`;var s=`PH`;var t=`southeast-asia`;var o=4;var r=81;var g={en:`Sinigang na Baboy`,ua:`Сініганг зі свинини`};var m={en:`Sinigang na Baboy is a dish from Philippines prepared with pork ribs, yellow onion, tomato, daikon. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Сініганг зі свинини, страва кухні країни Філіппіни, яку готують із таких продуктів: свинячі ребра, жовта цибуля, помідор, дайкон. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var d=[{en:`Combine these ingredients in a pot, bring just to a boil and skim any foam. Simmer gently for about 50 minutes to make a flavorful base.`,ua:`З’єднайте складники в каструлі, доведіть майже до кипіння та зніміть піну. Варіть на малому вогні приблизно 50 хвилин для насиченої основи.`,t:[`simmering`,`skimming-foam`],m:50,i:[[`pork-ribs`,850,`g`],[`water`,1700,`ml`],[`yellow-onion`,190,`g`],[`tomato`,250,`g`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 24 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 24 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:24,i:[[`daikon`,300,`g`],[`green-beans`,220,`g`],[`eggplant`,230,`g`]]},{en:`Stir in these seasonings and additions. Taste, adjust the balance and let the dish stand briefly before serving.`,ua:`Додайте приправи та завершальні складники. Спробуйте, збалансуйте смак і дайте страві трохи настоятися перед подаванням.`,t:[`seasoning`,`finishing-with-herbs`],m:4,i:[[`tamarind-concentrate`,65,`g`],[`fish-sauce`,45,`ml`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`spinach`,170,`g`]]}];var h={slug:n,id:a,country:`PH`,region:t,servings:4,minutes:81,title:g,text:m,steps:d};export{s as country,h as default,a as id,r as minutes,t as region,o as servings,n as slug,d as steps,m as text,g as title};